<template><view class="page"><PageScroller :loading="loading" @refresh="load"><view class="list"><view v-for="item in items" :key="item.id" class="card"><view class="card__top"><text class="card__title">{{item.name}}</text><text class="status" :class="item.enabled?'enabled':''">{{item.enabled?'已启用':'已停用'}}</text></view><text class="card__meta">周期：每 {{item.intervalMinutes}} 分钟\n检测：{{typeText(item.detectionTypes)}}\n通道：{{channelCount(item.channelIds)}} 个</text><button size="mini" class="run" :disabled="running===item.id" @click="run(item)">{{running===item.id?'正在创建任务':'立即巡检'}}</button></view><EmptyState v-if="!loading&&!items.length" title="暂无巡检计划" description="请先在管理后台创建巡检计划"/></view></PageScroller></view></template>
<script setup lang="ts">
import{ref}from'vue';import{onShow}from'@dcloudio/uni-app';import PageScroller from'@/components/PageScroller.vue';import EmptyState from'@/components/EmptyState.vue';import{queryInspectionPlans,runInspectionPlan,type InspectionPlan}from'@/api/inspection';import{showRequestError}from'@/utils/request';import{useAuthStore}from'@/stores/auth';const auth=useAuthStore(),items=ref<InspectionPlan[]>([]),loading=ref(false),running=ref<number>();async function load(){if(loading.value)return;loading.value=true;try{const r=await queryInspectionPlans();items.value=r.list||r.items||[]}catch(e){showRequestError(e)}finally{loading.value=false}}async function run(item:InspectionPlan){running.value=item.id;try{await runInspectionPlan(item.id);uni.showToast({title:'巡检任务已创建',icon:'success'})}catch(e){showRequestError(e)}finally{running.value=undefined}}function typeText(v:string){const names:Record<string,string>={BLACK_SCREEN:'黑屏',FREEZE:'冻结',BLUR:'模糊',OCCLUSION:'遮挡'};return v.split(',').map(i=>names[i]||i).join('、')}function channelCount(v?:string){return v?v.split(',').filter(Boolean).length:0}onShow(()=>{if(auth.requireAuth())load()})
</script><style lang="scss" scoped>@use '@/styles/list.scss';.page{height:100%;overflow:hidden}.status{padding:7rpx 14rpx;color:#667085;background:#edf0f5;border-radius:999rpx;font-size:21rpx}.status.enabled{color:#14804a;background:#e4f7ed}.run{margin:20rpx 0 0 auto;color:#2368f2;background:#eef4ff}</style>
